/* Chilly Vampirebat 53 by JesusRafaelNavaCruz — https://uiverse.io/JesusRafaelNavaCruz/chilly-vampirebat-53 */
.loader {
  width: 4rem;
  height: 4rem;
  border-radius: 50%;
  box-sizing: border-box;
  border-top: 8px solid #fff;
  border-left: 8px solid #fff;
  border-right: 8px solid #ff00;
  animation: loader .7s infinite linear;
}

@keyframes loader {
  to {
    transform: rotate(360deg);
  }
}
